//
// Kana Liga in JS: converts romaji to the kana the font draws for it,
// hiragana, or katakana for syllables typed all uppercase.
// It replays the font's GSUB lookups in the same order, so text copied
// from a Kana Liga element can be turned into the kana on screen.
//
// Generated by fonts/kana-liga/build.py from kana-liga.ts, data/romaji.tsv
// and data/words.tsv, do not edit.
//

//
// Types
//

// One glyph after the lookups: the kana (or leftover character) it shows,
// and the typed text it came from.
export type Syllable = { kana: string; romaji: string };

