// generated
const WORD_TABLE: Array<[string, string]> = [
	["wa", "は"],
	["konnichiwa", "こんにちは"],
	["konbanwa", "こんばんは"],
	["dewa", "では"],
	["mataha", "または"],
	["aruiwa", "あるいは"],
	["moshikuwa", "もしくは"],
	["sorewa", "それは"],
];

const VOWELS = "aeiou";
// letters that keep a preceding n from becoming ん
const N_KEEPERS = VOWELS + "y";
// doubled consonants that turn into っ, n is handled by the syllabic n rule
const SOKUON_CONSONANTS = "bcdfghjklmpqrstvwxyz";

const SMALL_TSU = "っ";
const SYLLABIC_N = "ん";
const LONG_VOWEL = "ー";

// a period or comma right after kana becomes these
const KANA_PUNCTUATION = new Map([
	[".", "。"],
	[",", "、"],
]);

// katakana sits 0x60 above the matching hiragana
const KATAKANA_OFFSET = 0x60;

// the same table as uppercase romaji to katakana
const UPPER_TABLE: Array<[string, string]> = ROMAJI_TABLE.map(([romaji, kana]) => [
	romaji.toUpperCase(),
	toKatakana(kana),
]);

const LIGATURES = longestFirst(ROMAJI_TABLE.filter(([romaji]) => romaji.length > 1));
const SINGLES = new Map(ROMAJI_TABLE.filter(([romaji]) => romaji.length === 1));
const UPPER_LIGATURES = longestFirst(UPPER_TABLE.filter(([romaji]) => romaji.length > 1));
const UPPER_SINGLES = new Map(UPPER_TABLE.filter(([romaji]) => romaji.length === 1));

// the first spelling the table lists for each kana, which is the Hepburn one
const KANA_TO_ROMAJI = new Map<string, string>();
for (const [romaji, kana] of ROMAJI_TABLE) {
	if (!KANA_TO_ROMAJI.has(kana)) KANA_TO_ROMAJI.set(kana, romaji);
}

//
// Functions
//

export function romajiToKana(text: string): string {
	return romajiToSyllables(text)
		.map((syllable) => syllable.kana)
		.join("");
}

// Kana glyphs never match a letter rule again, like in the font.
export function romajiToSyllables(text: string): Syllable[] {
	let glyphs = Array.from(text, (char) => ({ kana: char, romaji: char }));
	glyphs = substituteUpperSokuon(glyphs);
	glyphs = substituteLigatures(glyphs, [["N'", toKatakana(SYLLABIC_N)]]);
	glyphs = substituteUpperSyllabicN(glyphs);
	glyphs = substituteLigatures(glyphs, UPPER_LIGATURES);
	glyphs = substituteUpperVowels(glyphs);
	glyphs = glyphs.map((glyph) => (isUpperLetter(glyph.kana) ? { ...glyph, kana: glyph.kana.toLowerCase() } : glyph));
	glyphs = substituteWords(glyphs);
	glyphs = substituteSokuon(glyphs);
	glyphs = substituteLigatures(glyphs, [["n'", SYLLABIC_N]]);
	glyphs = substituteSyllabicN(glyphs);
	glyphs = substituteLigatures(glyphs, LIGATURES);
	glyphs = glyphs.map((glyph) => ({ ...glyph, kana: SINGLES.get(glyph.kana) ?? glyph.kana }));
	glyphs = substituteLongVowel(glyphs);
	return substituteKanaPunctuation(glyphs);
}

// The other way, for reading kana back: hiragana or katakana to romaji, with
// っ doubling the next consonant and ん written n' before a vowel or y.
// Katakana comes back uppercase, so the result is what to type for it.
// Anything that is not kana is kept as is.
export function kanaToRomaji(text: string): string {
	const kana = toHiragana(text);
	let result = "";
	let pending_tsu = 0;
	let is_pending_upper = false;
	let i = 0;

	while (i < kana.length) {
		const pair = kana.slice(i, i + 2);
		const char = kana[i];
		let romaji: string;
		let length = 1;

		const is_katakana = isKatakana(text[i]);

		if (pair.length === 2 && KANA_TO_ROMAJI.has(pair)) {
			romaji = KANA_TO_ROMAJI.get(pair)!;
			length = 2;
		} else if (char === SMALL_TSU) {
			pending_tsu += 1;
			is_pending_upper = is_katakana;
			i += 1;
			continue;
		} else if (char === SYLLABIC_N) {
			const next = KANA_TO_ROMAJI.get(kana.slice(i + 1, i + 3)) ?? KANA_TO_ROMAJI.get(kana[i + 1] ?? "") ?? "";
			romaji = next && N_KEEPERS.includes(next[0]) ? "n'" : "n";
		} else if (char === LONG_VOWEL) {
			romaji = "-";
		} else {
			romaji = KANA_TO_ROMAJI.get(char) ?? char;
		}

		if (pending_tsu) {
			const doubled = romaji.startsWith("ch") ? "t" : romaji[0];
			const is_consonant = /^[a-z]$/.test(doubled) && !VOWELS.includes(doubled);
			const tsu = (is_consonant ? doubled : "xtu").repeat(pending_tsu);
			result += is_pending_upper ? tsu.toUpperCase() : tsu;
			pending_tsu = 0;
		}

		result += is_katakana ? romaji.toUpperCase() : romaji;
		i += length;
	}

	const tsu = "xtu".repeat(pending_tsu);
	return result + (is_pending_upper ? tsu.toUpperCase() : tsu);
}

// toHiragana keeps the length, so i indexes both text and kana
function toHiragana(text: string) {
	return Array.from(text, (char) => {
		const codepoint = char.codePointAt(0)!;
		return codepoint >= 0x30a1 && codepoint <= 0x30f6 ? String.fromCodePoint(codepoint - KATAKANA_OFFSET) : char;
	}).join("");
}

function toKatakana(kana: string) {
	return Array.from(kana, (char) => {
		const codepoint = char.codePointAt(0)!;
		return codepoint >= 0x3041 && codepoint <= 0x3096 ? String.fromCodePoint(codepoint + KATAKANA_OFFSET) : char;
	}).join("");
}

function longestFirst(table: Array<[string, string]>) {
	return [...table].sort((a, b) => b[0].length - a[0].length);
}

// An uppercase doubled consonant is ッ only when an uppercase letter follows,
// so the next syllable decides: KITTE is katakana, KiTTe is not.
function substituteUpperSokuon(glyphs: Syllable[]) {
	return glyphs.map((glyph, i) => {
		const kana = glyph.kana;
		const is_doubled =
			SOKUON_CONSONANTS.toUpperCase().includes(kana) &&
			glyphs[i + 1]?.kana === kana &&
			isUpperLetter(glyphs[i + 2]?.kana);
		const is_tch = kana === "T" && glyphs[i + 1]?.kana === "C" && glyphs[i + 2]?.kana === "H";
		return is_doubled || is_tch ? { ...glyph, kana: toKatakana(SMALL_TSU) } : glyph;
	});
}

// a vowel or y of either case keeps N, so Na is left for な
function substituteUpperSyllabicN(glyphs: Syllable[]) {
	return glyphs.map((glyph, i) => {
		const next = glyphs[i + 1]?.kana;
		const is_kept = next !== undefined && next.length === 1 && N_KEEPERS.includes(next.toLowerCase());
		return glyph.kana === "N" && !is_kept ? { ...glyph, kana: toKatakana(SYLLABIC_N) } : glyph;
	});
}

// An uppercase vowel is katakana only next to katakana or another capital,
// so a capitalized sentence (Arigatou, Ohayou) stays hiragana. In place,
// like the font, so a converted vowel is context for the next one.
function substituteUpperVowels(glyphs: Syllable[]) {
	const result = [...glyphs];

	for (let i = 0; i < result.length; i++) {
		const katakana = UPPER_SINGLES.get(result[i].kana);
		const before = result[i - 1]?.kana;
		const after = result[i + 1]?.kana;
		const has_neighbor =
			isKatakana(before?.at(-1)) || isUpperLetter(before) || isKatakana(after?.[0]) || isUpperLetter(after);
		if (katakana && has_neighbor) result[i] = { ...result[i], kana: katakana };
	}

	return result;
}

function substituteWords(glyphs: Syllable[]) {
	const result: Syllable[] = [];
	let i = 0;

	while (i < glyphs.length) {
		const word = WORD_TABLE.find(([romaji]) => matchesAt(glyphs, i, romaji));

		const before = glyphs[i - 1]?.kana;
		const after = glyphs[i + (word?.[0].length ?? 0)]?.kana;
		const is_alone = !isLetter(before) && !isKatakana(before?.at(-1)) && !isLetter(after) && !isKatakana(after?.[0]);

		if (word && is_alone) {
			result.push(merge(glyphs, i, word[0].length, word[1]));
			i += word[0].length;
		} else {
			result.push(glyphs[i]);
			i += 1;
		}
	}

	return result;
}

function substituteSokuon(glyphs: Syllable[]) {
	return glyphs.map((glyph, i) => {
		const kana = glyph.kana;
		const is_doubled = SOKUON_CONSONANTS.includes(kana) && glyphs[i + 1]?.kana === kana;
		const is_tch = kana === "t" && glyphs[i + 1]?.kana === "c" && glyphs[i + 2]?.kana === "h";
		return is_doubled || is_tch ? { ...glyph, kana: SMALL_TSU } : glyph;
	});
}

function substituteSyllabicN(glyphs: Syllable[]) {
	return glyphs.map((glyph, i) => {
		const next = glyphs[i + 1]?.kana;
		const is_kept = next !== undefined && next.length === 1 && N_KEEPERS.includes(next);
		return glyph.kana === "n" && !is_kept ? { ...glyph, kana: SYLLABIC_N } : glyph;
	});
}

// longest match first, left to right, like a GSUB ligature lookup
function substituteLigatures(glyphs: Syllable[], table: Array<[string, string]>) {
	const result: Syllable[] = [];
	let i = 0;

	while (i < glyphs.length) {
		const entry = table.find(([romaji]) => matchesAt(glyphs, i, romaji));

		if (entry) {
			result.push(merge(glyphs, i, entry[0].length, entry[1]));
			i += entry[0].length;
		} else {
			result.push(glyphs[i]);
			i += 1;
		}
	}

	return result;
}

// in place, so a hyphen after ー also becomes ー
function substituteLongVowel(glyphs: Syllable[]) {
	const result = [...glyphs];

	for (let i = 1; i < result.length; i++) {
		if (result[i].kana === "-" && isKana(result[i - 1].kana.at(-1))) result[i] = { ...result[i], kana: LONG_VOWEL };
	}

	return result;
}

// in place like the long vowel, though 。 and 、 are not kana themselves
function substituteKanaPunctuation(glyphs: Syllable[]) {
	const result = [...glyphs];

	for (let i = 1; i < result.length; i++) {
		const punctuation = KANA_PUNCTUATION.get(result[i].kana);
		if (punctuation && isKana(result[i - 1].kana.at(-1))) result[i] = { ...result[i], kana: punctuation };
	}

	return result;
}

function merge(glyphs: Syllable[], start: number, length: number, kana: string): Syllable {
	const romaji = glyphs
		.slice(start, start + length)
		.map((glyph) => glyph.romaji)
		.join("");
	return { kana, romaji };
}

function matchesAt(glyphs: Syllable[], start: number, romaji: string) {
	for (let i = 0; i < romaji.length; i++) {
		if (glyphs[start + i]?.kana !== romaji[i]) return false;
	}
	return true;
}

function isLetter(glyph: string | undefined) {
	return glyph !== undefined && /^[a-zA-Z]$/.test(glyph);
}

function isUpperLetter(char: string | undefined) {
	return char !== undefined && char.length === 1 && char >= "A" && char <= "Z";
}

function isKana(char: string | undefined) {
	if (char === undefined) return false;
	const codepoint = char.codePointAt(0)!;
	return (codepoint >= 0x3041 && codepoint <= 0x309f) || (codepoint >= 0x30a1 && codepoint <= 0x30fc);
}

function isKatakana(char: string | undefined) {
	if (char === undefined) return false;
	const codepoint = char.codePointAt(0)!;
	return codepoint >= 0x30a1 && codepoint <= 0x30f6;
}
